{
  "name": "pi-review-loop",
  "version": "0.4.4",
  "description": "Automated code review loop extension for pi coding agent",
  "files": [
    "index.ts",
    "settings.ts",
    "review-loop.png",
    "prompts/"
  ],
  "keywords": [
    "pi-package",
    "pi",
    "pi-coding-agent",
    "extension",
    "code-review",
    "automation",
    "ralph-wiggum-loop"
  ],
  "author": "Nico Bailon",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicobailon/pi-review-loop.git"
  },
  "bugs": {
    "url": "https://github.com/nicobailon/pi-review-loop/issues"
  },
  "homepage": "https://github.com/nicobailon/pi-review-loop#readme",
  "pi": {
    "extensions": [
      "./index.ts"
    ],
    "prompts": [
      "./prompts"
    ]
  }
}

import { readFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { homedir } from "node:os";
import { fileURLToPath } from "node:url";

export const SETTINGS_PATH = join(homedir(), ".pi", "agent", "settings.json");
const PACKAGE_DIR = dirname(fileURLToPath(import.meta.url));
const PACKAGE_PROMPTS_DIR = join(PACKAGE_DIR, "prompts");

export const DEFAULT_MAX_ITERATIONS = 7;

export const DEFAULT_REVIEW_PROMPT = `Great, now I want you to carefully read over all of the new code you just wrote and other existing code with "fresh eyes," looking super carefully for any obvious bugs, errors, problems, issues, confusion, etc. Also, if you notice any pre-existing issues/bugs those should be addressed.

Question everything: Does each line of code need to exist? Unused parameters, dead code, and unnecessary complexity should be removed, not dressed up with underscore prefixes or comments.

This codebase will outlive you. Every shortcut becomes someone else's burden. Every hack compounds into technical debt that slows the whole team down.

You are not just writing code. You are shaping the future of this project. The patterns you establish will be copied. The corners you cut will be cut again.

Fight entropy. Leave the codebase better than you found it.

You MUST read all relevant code and think deeply (ultrathink!!!) first before you make any edits.

**Response format:**
- If you find ANY issues: fix them, then list what you fixed. Do NOT say "no issues found" - instead end with "Fixed [N] issue(s). Ready for another review."
- If you find ZERO issues: describe what you examined and verified, then conclude with "No issues found."

Do not rush to a verdict. Read all relevant code first, trace through edge cases, and only then decide. I am pushing you to do a genuinely thorough review and not just lazily rubber-stamp it. Make sure you think deeply, then ultrathink some more.`;

export const DEFAULT_PLAN_REVIEW_PROMPT = `Great, now I want you to carefully read over the plan/spec and compare against the codebase with "fresh eyes," looking super carefully for any obvious bugs, errors, problems, issues, confusion, etc. Think through how best to implement this elegantly given our architecture and goals. Also keep in mind that this is not an MVP - so don't skip anything.

**CRITICAL: This reviews and fixes the PLAN DOCUMENT ONLY. Do NOT edit, create, or modify any source code files. Only the plan/spec file itself should be edited. If you find issues in the plan, fix them in the plan. Do NOT implement the plan or write any code.**

**Response format:**
- If you find ANY issues: fix them in the plan, then list what you fixed. Do NOT say "no issues found" - instead end with "Fixed [N] issue(s). Ready for another review."
- If you find ZERO issues: describe what you examined and verified, then conclude with "No issues found."

Do not rush to a verdict. Read all relevant code first, trace through edge cases, and only then decide. I am pushing you to do a genuinely thorough review and not just lazily rubber-stamp it. Make sure you think deeply, then ultrathink some more.`;

export const DEFAULT_TRIGGER_PATTERNS: RegExp[] = [
  /\bimplement\s+(the\s+)?plan\b/i,
  /\bimplement\s+(the\s+)?spec\b/i,
  /\bimplement\s+(this\s+)?plan\b/i,
  /\bimplement\s+(this\s+)?spec\b/i,
  /\bstart\s+implementing\b.*\b(plan|spec)\b/i,
  /\bgo\s+ahead\s+and\s+implement\b.*\b(plan|spec)\b/i,
  /\blet'?s\s+implement\b.*\b(plan|spec)\b/i,
  /\b(plan|spec)\b.*\bstart\s+implementing\b/i,
  /\b(plan|spec)\b.*\bgo\s+ahead\s+and\s+implement\b/i,
  /\b(plan|spec)\b.*\blet'?s\s+implement\b/i,
  /read over all of the new code.*fresh eyes/i,
];

export const DEFAULT_EXIT_PATTERNS: RegExp[] = [
  /no\s+(\w+\s+)?issues\s+found/i,
  /no\s+(\w+\s+)?bugs\s+found/i,
  /(?:^|\n)\s*(?:looks\s+good|all\s+good)[\s.,!]*(?:$|\n)/im,
];

export const DEFAULT_ISSUES_FIXED_PATTERNS: RegExp[] = [
  /issues?\s+(i\s+)?fixed/i,
  /fixed\s+(the\s+)?(following|these|this|issues?|bugs?)/i,
  /fixed\s+\d+\s+issues?/i,
  /found\s+and\s+(fixed|corrected|resolved)/i,
  /bugs?\s+(i\s+)?fixed/i,
  /corrected\s+(the\s+)?(following|these|this)/i,
  /(?<!no\s)issues?\s+(i\s+)?(found|identified|discovered)/i,
  /(?<!no\s)problems?\s+(i\s+)?(found|identified|discovered)/i,
  /changes?\s+(i\s+)?made/i,
  /here'?s?\s+what\s+(i\s+)?(fixed|changed|corrected)/i,
  /(issues|bugs|problems|changes|fixes)\s*:/i,
  /ready\s+for\s+(another|the\s+next)\s+review/i,
];

export interface PatternConfig {
  mode?: "extend" | "replace";
  patterns: string[];
}

export interface ReviewPromptConfig {
  type: "inline" | "file" | "template";
  value: string;
}

export interface ReviewerLoopSettingsRaw {
  maxIterations?: number;
  reviewPrompt?: string;
  autoTrigger?: boolean;
  freshContext?: boolean;
  triggerPatterns?: PatternConfig;
  exitPatterns?: PatternConfig;
  issuesFixedPatterns?: PatternConfig;
}

export interface ReviewerLoopSettings {
  maxIterations: number;
  reviewPromptConfig: ReviewPromptConfig;
  autoTrigger: boolean;
  freshContext: boolean;
  triggerPatterns: RegExp[];
  exitPatterns: RegExp[];
  issuesFixedPatterns: RegExp[];
}

function parsePattern(input: unknown): RegExp | null {
  if (typeof input !== "string") return null;

  const match = input.match(/^\/(.+)\/([gimsuy]*)$/);
  if (match) {
    try {
      const flags = match[2].replace(/g/g, "");
      return new RegExp(match[1], flags);
    } catch {
      return null;
    }
  }
  const escaped = input.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(escaped, "i");
}

function loadPatterns(
  config: PatternConfig | undefined,
  defaults: RegExp[]
): RegExp[] {
  if (!config?.patterns || !Array.isArray(config.patterns) || config.patterns.length === 0) {
    return defaults;
  }

  const userPatterns = config.patterns
    .map(parsePattern)
    .filter((p): p is RegExp => p !== null);

  if (config.mode === "replace") {
    return userPatterns.length > 0 ? userPatterns : defaults;
  }

  return [...defaults, ...userPatterns];
}

function isFilePath(value: string): boolean {
  return (
    value.startsWith("~/") ||
    value.startsWith("/") ||
    value.startsWith("./") ||
    value.endsWith(".md") ||
    value.endsWith(".txt")
  );
}

function parseReviewPromptConfig(value: string | undefined): ReviewPromptConfig {
  if (!value) {
    return { type: "inline", value: DEFAULT_REVIEW_PROMPT };
  }

  if (value.startsWith("template:")) {
    const templateName = value.slice("template:".length).trim();
    return { type: "template", value: templateName };
  }

  if (isFilePath(value)) {
    return { type: "file", value };
  }

  return { type: "inline", value };
}

function stripFrontmatter(content: string): string {
  const match = content.match(/^---\r?\n[\s\S]*?\r?\n---(?:\r?\n)?([\s\S]*)$/);
  return match ? match[1].trim() : content.trim();
}

function resolvePath(value: string): string {
  if (value.startsWith("~/")) {
    return join(homedir(), value.slice(2));
  }
  return value;
}

function getTemplateDefaultPrompt(templateName: string): string {
  if (templateName === "double-check-plan") {
    return DEFAULT_PLAN_REVIEW_PROMPT;
  }
  return DEFAULT_REVIEW_PROMPT;
}

export function getReviewPrompt(config: ReviewPromptConfig): string {
  switch (config.type) {
    case "inline":
      return config.value || DEFAULT_REVIEW_PROMPT;

    case "file": {
      const resolvedPath = resolvePath(config.value);
      try {
        const content = readFileSync(resolvedPath, "utf-8").trim();
        return content || DEFAULT_REVIEW_PROMPT;
      } catch {
        return DEFAULT_REVIEW_PROMPT;
      }
    }

    case "template": {
      const templateName = config.value.trim();
      const templatePaths = [
        join(homedir(), ".pi", "agent", "prompts", `${templateName}.md`),
        join(PACKAGE_PROMPTS_DIR, `${templateName}.md`),
      ];

      for (const templatePath of templatePaths) {
        try {
          if (!existsSync(templatePath)) continue;
          let content = readFileSync(templatePath, "utf-8");
          content = stripFrontmatter(content);
          content = content.replace(/\$@/g, "").trim();
          if (content) return content;
        } catch {
          // Try next location
        }
      }

      return getTemplateDefaultPrompt(templateName);
    }
  }
}

export function loadSettings(): ReviewerLoopSettings {
  let raw: ReviewerLoopSettingsRaw = {};

  try {
    const content = readFileSync(SETTINGS_PATH, "utf-8");
    const parsed = JSON.parse(content);
    raw = parsed?.reviewerLoop ?? {};
  } catch {
    // Use all defaults
  }

  return {
    maxIterations:
      typeof raw.maxIterations === "number" && raw.maxIterations >= 1
        ? raw.maxIterations
        : DEFAULT_MAX_ITERATIONS,
    reviewPromptConfig: parseReviewPromptConfig(raw.reviewPrompt),
    autoTrigger: raw.autoTrigger === true,
    freshContext: raw.freshContext === true,
    triggerPatterns: loadPatterns(raw.triggerPatterns, DEFAULT_TRIGGER_PATTERNS),
    exitPatterns: loadPatterns(raw.exitPatterns, DEFAULT_EXIT_PATTERNS),
    issuesFixedPatterns: loadPatterns(
      raw.issuesFixedPatterns,
      DEFAULT_ISSUES_FIXED_PATTERNS
    ),
  };
}

import type { ExtensionAPI, ExtensionContext } from "@mariozechner/pi-coding-agent";
import { Type } from "@sinclair/typebox";
import { loadSettings, getReviewPrompt, type ReviewerLoopSettings, type ReviewPromptConfig } from "./settings.js";

export default function (pi: ExtensionAPI) {
  let settings: ReviewerLoopSettings = loadSettings();
  let reviewModeActive = false;
  let currentIteration = 0;
  let customPromptSuffix = "";
  let freshContext = settings.freshContext;
  let reviewBoundaryCount = -1;
  let boundaryNeedsCapture = false;
  let activePromptConfig: ReviewPromptConfig = settings.reviewPromptConfig;

  function updateStatus(ctx: ExtensionContext) {
    if (reviewModeActive) {
      const parts = [`Review mode (${currentIteration + 1}/${settings.maxIterations})`];
      if (freshContext) parts.push("fresh");
      ctx.ui.setStatus("review-loop", parts.join(" | "));
    } else {
      ctx.ui.setStatus("review-loop", undefined);
    }
  }

  function buildReviewPrompt(promptConfig: ReviewPromptConfig): string {
    const basePrompt = getReviewPrompt(promptConfig);
    if (customPromptSuffix) {
      return `${basePrompt}\n\n**Additional focus:** ${customPromptSuffix}`;
    }
    return basePrompt;
  }

  function parseCustomText(args: string): string {
    const trimmed = args.trim();
    if (!trimmed) return "";

    const match = trimmed.match(/^"(.+)"$/s) || trimmed.match(/^'(.+)'$/s);
    return match ? match[1].trim() : trimmed;
  }

  function exitReviewMode(ctx: ExtensionContext, reason: string) {
    reviewModeActive = false;
    currentIteration = 0;
    customPromptSuffix = "";
    reviewBoundaryCount = -1;
    boundaryNeedsCapture = false;
    activePromptConfig = settings.reviewPromptConfig;
    updateStatus(ctx);
    ctx.ui.notify(`Review mode ended: ${reason}`, "info");
  }

  function enterReviewMode(ctx: ExtensionContext) {
    reviewModeActive = true;
    currentIteration = 0;
    reviewBoundaryCount = -1;
    boundaryNeedsCapture = false;
    updateStatus(ctx);
    ctx.ui.notify("Review mode activated", "info");
  }

  pi.on("session_start", async (_event, ctx) => {
    settings = loadSettings();
    freshContext = settings.freshContext;
    activePromptConfig = settings.reviewPromptConfig;
    reviewModeActive = false;
    currentIteration = 0;
    customPromptSuffix = "";
    reviewBoundaryCount = -1;
    boundaryNeedsCapture = false;
    if (ctx.hasUI) updateStatus(ctx);
  });

  pi.on("input", async (event, ctx) => {
    if (!ctx.hasUI) return { action: "continue" as const };

    const isTrigger = settings.autoTrigger && settings.triggerPatterns.some((p) => p.test(event.text));

    if (reviewModeActive && event.source === "interactive" && !isTrigger) {
      exitReviewMode(ctx, "user interrupted");
      return { action: "continue" as const };
    }

    if (isTrigger && !reviewModeActive) {
      enterReviewMode(ctx);
    }

    return { action: "continue" as const };
  });

  pi.on("before_agent_start", async (event, ctx) => {
    if (!ctx.hasUI) return;
    if (reviewModeActive) return;
    if (!settings.autoTrigger) return;

    const isTrigger = settings.triggerPatterns.some((p) => p.test(event.prompt));
    if (isTrigger) {
      enterReviewMode(ctx);
    }
  });

  pi.on("context", async (event) => {
    if (!reviewModeActive || !freshContext) return;

    const messages = event.messages;
    if (messages.length === 0) return;

    if (boundaryNeedsCapture) {
      for (let i = messages.length - 1; i >= 0; i--) {
        if (messages[i].role === "user") {
          reviewBoundaryCount = i;
          break;
        }
      }
      boundaryNeedsCapture = false;
    }

    if (currentIteration === 0) return;
    if (reviewBoundaryCount < 0) return;

    let lastUserIdx = -1;
    for (let i = messages.length - 1; i >= 0; i--) {
      if (messages[i].role === "user") {
        lastUserIdx = i;
        break;
      }
    }
    if (lastUserIdx < 0) return;
    if (reviewBoundaryCount >= lastUserIdx) return;

    const preReview = messages.slice(0, reviewBoundaryCount);
    const currentIterationMsgs = messages.slice(lastUserIdx);

    const assembled: typeof messages = [...preReview];

    assembled.push({
      role: "user",
      content: [{
        type: "text",
        text: `[Review pass ${currentIteration + 1}. ${currentIteration} prior pass(es) completed, fixes applied to code. Re-read any relevant plan, spec, PRD, or progress documents before reviewing. Review with fresh eyes.]`,
      }],
      timestamp: Date.now(),
    } as any);

    assembled.push(...currentIterationMsgs);

    return { messages: assembled };
  });

  pi.on("agent_end", async (event, ctx) => {
    if (!ctx.hasUI) return;
    if (!reviewModeActive) return;

    const assistantMessages = event.messages.filter((m) => m.role === "assistant");
    const lastAssistantMessage = assistantMessages[assistantMessages.length - 1];

    if (!lastAssistantMessage) {
      exitReviewMode(ctx, "aborted");
      return;
    }

    const textContent = lastAssistantMessage.content
      .filter((c): c is { type: "text"; text: string } => c.type === "text")
      .map((c) => c.text)
      .join("\n");

    if (!textContent.trim()) {
      exitReviewMode(ctx, "aborted");
      return;
    }

    const hasExitPhrase = settings.exitPatterns.some((p) => p.test(textContent));
    const hasIssuesFixed = settings.issuesFixedPatterns.some((p) =>
      p.test(textContent)
    );

    if (hasExitPhrase && !hasIssuesFixed) {
      exitReviewMode(ctx, "no issues found");
      return;
    }

    currentIteration++;
    if (currentIteration >= settings.maxIterations) {
      exitReviewMode(ctx, `max iterations (${settings.maxIterations}) reached`);
      return;
    }

    if (freshContext && reviewBoundaryCount < 0) boundaryNeedsCapture = true;
    updateStatus(ctx);
    pi.sendUserMessage(buildReviewPrompt(activePromptConfig), {
      deliverAs: "followUp",
    });
  });

  pi.registerCommand("review-start", {
    description: "Activate review loop with optional custom focus text.",
    handler: async (args, ctx) => {
      if (reviewModeActive) {
        ctx.ui.notify("Review mode is already active", "info");
      } else {
        customPromptSuffix = parseCustomText(args);
        activePromptConfig = settings.reviewPromptConfig;
        enterReviewMode(ctx);
        if (freshContext && reviewBoundaryCount < 0) boundaryNeedsCapture = true;
        pi.sendUserMessage(buildReviewPrompt(activePromptConfig));
      }
    },
  });

  pi.registerCommand("review-plan", {
    description: "Activate review loop for plans/specs/PRDs with optional custom focus text.",
    handler: async (args, ctx) => {
      if (reviewModeActive) {
        ctx.ui.notify("Review mode is already active", "info");
      } else {
        customPromptSuffix = parseCustomText(args);
        activePromptConfig = { type: "template", value: "double-check-plan" };
        enterReviewMode(ctx);
        if (freshContext && reviewBoundaryCount < 0) boundaryNeedsCapture = true;
        pi.sendUserMessage(buildReviewPrompt(activePromptConfig));
      }
    },
  });

  pi.registerCommand("review-max", {
    description: "Set max review iterations (default: 7)",
    handler: async (args, ctx) => {
      const num = parseInt(args, 10);
      if (isNaN(num) || num < 1) {
        ctx.ui.notify("Usage: /review-max <number>", "error");
        return;
      }
      settings.maxIterations = num;
      ctx.ui.notify(`Max review iterations set to ${settings.maxIterations}`, "info");
    },
  });

  pi.registerCommand("review-exit", {
    description: "Exit review mode manually",
    handler: async (_args, ctx) => {
      if (reviewModeActive) {
        exitReviewMode(ctx, "manual exit");
      } else {
        ctx.ui.notify("Review mode is not active", "info");
      }
    },
  });

  pi.registerCommand("review-status", {
    description: "Show review mode status",
    handler: async (_args, ctx) => {
      if (reviewModeActive) {
        const parts = [`iteration ${currentIteration + 1}/${settings.maxIterations}`];
        if (freshContext) parts.push("fresh context");
        ctx.ui.notify(`Review mode active: ${parts.join(", ")}`, "info");
      } else {
        ctx.ui.notify(
          `Review mode inactive (max: ${settings.maxIterations}, auto-trigger: ${settings.autoTrigger ? "on" : "off"}, fresh: ${freshContext ? "on" : "off"})`,
          "info"
        );
      }
    },
  });

  pi.registerCommand("review-auto", {
    description: "Toggle auto-trigger, or start review with custom focus: /review-auto focus on X",
    handler: async (args, ctx) => {
      const arg = args.trim();
      const argLower = arg.toLowerCase();

      if (argLower === "on" || argLower === "true" || argLower === "1") {
        settings.autoTrigger = true;
        ctx.ui.notify(`Auto-trigger enabled`, "info");
        return;
      }
      if (argLower === "off" || argLower === "false" || argLower === "0") {
        settings.autoTrigger = false;
        ctx.ui.notify(`Auto-trigger disabled`, "info");
        return;
      }
      if (arg === "") {
        settings.autoTrigger = !settings.autoTrigger;
        ctx.ui.notify(
          `Auto-trigger ${settings.autoTrigger ? "enabled" : "disabled"}`,
          "info"
        );
        return;
      }

      settings.autoTrigger = true;
      customPromptSuffix = parseCustomText(arg);
      if (reviewModeActive) {
        ctx.ui.notify(`Auto-trigger enabled, focus updated for next iteration`, "info");
      } else {
        activePromptConfig = settings.reviewPromptConfig;
        enterReviewMode(ctx);
        if (freshContext && reviewBoundaryCount < 0) boundaryNeedsCapture = true;
        pi.sendUserMessage(buildReviewPrompt(activePromptConfig));
        ctx.ui.notify(`Auto-trigger enabled, review started with custom focus`, "info");
      }
    },
  });

  pi.registerCommand("review-fresh", {
    description: "Toggle fresh context mode for review iterations",
    handler: async (args, ctx) => {
      const arg = args.trim().toLowerCase();

      if (arg === "on" || arg === "true" || arg === "1") {
        freshContext = true;
      } else if (arg === "off" || arg === "false" || arg === "0") {
        freshContext = false;
      } else {
        freshContext = !freshContext;
      }
      ctx.ui.notify(`Fresh context ${freshContext ? "enabled" : "disabled"}`, "info");
    },
  });

  pi.registerTool({
    name: "review_loop",
    description:
      "Control the automated code review loop. Start/stop review mode, toggle auto-trigger, or check status. When started, the loop repeatedly prompts for code review until 'No issues found' or max iterations reached.",
    promptSnippet: "Start, stop, or inspect the automated review loop state",
    parameters: Type.Object({
      start: Type.Optional(
        Type.Boolean({
          description: "Start review mode and send the review prompt",
        })
      ),
      stop: Type.Optional(
        Type.Boolean({
          description: "Stop review mode",
        })
      ),
      autoTrigger: Type.Optional(
        Type.Boolean({
          description: "Enable/disable auto-trigger from keywords (disabled by default)",
        })
      ),
      maxIterations: Type.Optional(
        Type.Number({
          description: "Set max iterations (can be combined with start)",
          minimum: 1,
        })
      ),
      focus: Type.Optional(
        Type.String({
          description: "Custom focus/instructions to append to the review prompt (e.g., \"focus on error handling\")",
        })
      ),
      freshContext: Type.Optional(
        Type.Boolean({
          description: "Enable/disable fresh context mode (strips prior review iterations from context)",
        })
      ),
    }),

    async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
      if (typeof params.maxIterations === "number" && params.maxIterations >= 1) {
        settings.maxIterations = params.maxIterations;
      }

      if (typeof params.autoTrigger === "boolean") {
        settings.autoTrigger = params.autoTrigger;
        ctx.ui.notify(
          `Auto-trigger ${settings.autoTrigger ? "enabled" : "disabled"}`,
          "info"
        );
      }

      if (typeof params.focus === "string") {
        customPromptSuffix = params.focus.trim();
      }

      if (typeof params.freshContext === "boolean") {
        freshContext = params.freshContext;
        ctx.ui.notify(
          `Fresh context ${freshContext ? "enabled" : "disabled"}`,
          "info"
        );
      }

      if (params.start) {
        if (reviewModeActive) {
          return {
            content: [
              {
                type: "text",
                text: JSON.stringify({
                  active: true,
                  currentIteration,
                  maxIterations: settings.maxIterations,
                  autoTrigger: settings.autoTrigger,
                  freshContext,
                  focus: customPromptSuffix || undefined,
                  message: "Review mode is already active",
                }),
              },
            ],
          };
        }

        activePromptConfig = settings.reviewPromptConfig;
        enterReviewMode(ctx);
        if (freshContext && reviewBoundaryCount < 0) boundaryNeedsCapture = true;
        pi.sendUserMessage(buildReviewPrompt(activePromptConfig));

        return {
          content: [
            {
              type: "text",
              text: JSON.stringify({
                active: true,
                currentIteration,
                maxIterations: settings.maxIterations,
                autoTrigger: settings.autoTrigger,
                freshContext,
                focus: customPromptSuffix || undefined,
                message: customPromptSuffix
                  ? `Review mode started with custom focus. Review prompt sent.`
                  : "Review mode started. Review prompt sent.",
              }),
            },
          ],
        };
      }

      if (params.stop) {
        if (!reviewModeActive) {
          return {
            content: [
              {
                type: "text",
                text: JSON.stringify({
                  active: false,
                  currentIteration: 0,
                  maxIterations: settings.maxIterations,
                  autoTrigger: settings.autoTrigger,
                  freshContext,
                  message: "Review mode is not active",
                }),
              },
            ],
          };
        }

        exitReviewMode(ctx, "stopped by agent");

        return {
          content: [
            {
              type: "text",
              text: JSON.stringify({
                active: false,
                currentIteration: 0,
                maxIterations: settings.maxIterations,
                autoTrigger: settings.autoTrigger,
                freshContext,
                message: "Review mode stopped",
              }),
            },
          ],
        };
      }

      return {
        content: [
          {
            type: "text",
            text: JSON.stringify({
              active: reviewModeActive,
              currentIteration,
              maxIterations: settings.maxIterations,
              autoTrigger: settings.autoTrigger,
              freshContext,
              focus: customPromptSuffix || undefined,
              message: reviewModeActive
                ? `Review mode active: iteration ${currentIteration + 1}/${settings.maxIterations}`
                : "Review mode inactive",
            }),
          },
        ],
      };
